/// `xs[i]` in code: item `i` of a list, counted from 1 (conformance/lists.json).
pub fn at<T>(list: &[T], position: i64) -> Result<&T> {
    let len = list.len();
    usize::try_from(position).ok().and_then(|p| p.checked_sub(1)).and_then(|i| list.get(i)).ok_or_else(|| outside(position, len))
}

/// `xs[i] = value` in code: item `i` of a list to set, counted from 1.
pub fn at_mut<T>(list: &mut [T], position: i64) -> Result<&mut T> {
    let len = list.len();
    usize::try_from(position).ok().and_then(|p| p.checked_sub(1)).and_then(|i| list.get_mut(i)).ok_or_else(|| outside(position, len))
}

fn outside(position: i64, len: usize) -> Error {
    Error::Outside { position, count: len }
}

/// `round(value, places)` in code: at most `places` decimals, rounded half
/// away from zero; a value with fewer stays as it is, and places below 0
/// count as 0 (conformance/rounding.json).
pub fn round(value: Decimal, places: i64) -> Decimal {
    let places = places.clamp(0, 28) as u32;
    if value.scale() <= places {
        return value;
    }
    value.round_dp_with_strategy(places, rust_decimal::RoundingStrategy::MidpointAwayFromZero)
}

/// `snapped(value, step)`: the multiple of `step` nearest to `value`, a half
/// rounding up; a step of 0 gives the value (conformance/drawing.json, grids).
/// `a div b` in code: the quotient of two whole numbers, rounded toward zero.
pub fn whole_div(a: i64, b: i64) -> Result<i64> {
    if b == 0 { Err(Error::DividedByZero) } else { Ok(a.wrapping_div(b)) }
}

/// `a mod b` in code: what is left of `a div b`, with the sign of `a`.
pub fn whole_mod(a: i64, b: i64) -> Result<i64> {
    if b == 0 { Err(Error::DividedByZero) } else { Ok(a.wrapping_rem(b)) }
}

pub fn snapped(value: i64, step: i64) -> i64 {
    if step > 0 { (2 * value + step).div_euclid(2 * step) * step } else { value }
}

/// Runs a handler of an edit as one undo step (DESIGN 5.29): the reply
/// carries the step's id when the handler changed the database.
pub fn stepped(db: &Db, run: impl FnOnce() -> Result<ui::Reply>) -> Result<ui::Reply> {
    let before = db.last_step();
    let mut reply = db.step(run)?;
    if db.last_step() != before {
        reply.step = db.last_step();
    }
    Ok(reply)
}

/// Fail safe: runs a handler on the database. An error is what the screen
/// shows (a refusal its own text); a panic, as on a list index out of range,
/// becomes an error too, and the database stays usable for the next handler.
pub fn run_guarded<T>(db: &std::sync::Mutex<Db>, run: impl FnOnce(&Db) -> Result<T>) -> std::result::Result<T, serde_json::Value> {
    program::guarded(db, run).map_err(|said| serde_json::to_value(said).unwrap_or_default())
}

/// `sin(degrees)` in code, rounded to 10 decimals (conformance/drawing.json).
pub fn sin(degrees: Decimal) -> Decimal {
    angle(degrees, f64::sin)
}

/// `cos(degrees)` in code, rounded to 10 decimals (conformance/drawing.json).
pub fn cos(degrees: Decimal) -> Decimal {
    angle(degrees, f64::cos)
}

fn angle(degrees: Decimal, of: fn(f64) -> f64) -> Decimal {
    use rust_decimal::prelude::ToPrimitive;
    let radians = degrees.to_f64().unwrap_or(0.0).to_radians();
    let value = Decimal::from_f64_retain(of(radians)).unwrap_or_default();
    // Rounded, so every runtime gives the same; -0 is 0.
    round(value, 10).normalize()
}

/// A value of code as a number a canvas draws with.
pub fn units(value: Decimal) -> f64 {
    use rust_decimal::prelude::ToPrimitive;
    value.to_f64().unwrap_or(0.0)
}

/// The key of a stored record; 0 until it is saved for the first time.
pub type Id = i64;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Error {
    /// A `require` or `ensure` of a function or action did not hold.
    Contract(String),
    /// A record that should exist does not.
    NotFound { table: &'static str, id: Option<Id> },
    /// Another record refers to the record being deleted.
    InUse { table: &'static str, id: Id },
    /// A stored value does not fit its field.
    Invalid(String),
    Storage(String),
    /// A database connects with a secret setting (DESIGN 5.27) that the
    /// person has not kept yet: the setting's name.
    NotKept(String),
    /// A data event refused a save or delete, or code refused to go on, in
    /// its own words.
    Refused(ui::Text),
    /// An engine could not load, or failed while it ran (DESIGN 5.11).
    Engine(String),
    /// A value in code that does not fit where it is used: a highest
    /// number below 1, JSON that does not fit (conformance/lists.json).
    Value(String),
    /// `xs[i]` with no item `position` in a list of `count` (conformance/lists.json).
    Outside { position: i64, count: usize },
    /// `a div 0` or `a mod 0` in code.
    DividedByZero,
    /// A save refused a record whose required field is empty: the record's
    /// table and id, the field's column, and why in Clarity's own words. A
    /// window shows it at the input bound to that field (crate::required).
    Required { table: &'static str, id: Id, column: String, text: ui::Text },
}

/// Why an undo is refused: what it would take back was changed since, in
/// Clarity's own words with their English (as the C# runtime says it).
pub fn undo_changed_since() -> ui::Text {
    ui::Text::keyed("undoChangedSince", "This was changed since, so it cannot be taken back")
}

/// Why an undo is refused when its step is older than the ones kept (`UNDO_STEPS`).
pub fn undo_too_old() -> ui::Text {
    ui::Text::keyed("undoTooOld", "This was done too long ago to take back")
}

/// Why a save or a delete is refused: someone saved the record since it was
/// read (conformance/versions.json), in Clarity's own words with their English.
pub fn saved_since() -> ui::Text {
    ui::Text::keyed("savedSince", "Someone else changed this record since you opened it. Reload it to see their change.")
}

/// How many undo steps are kept: the oldest goes when a newer one comes, so a
/// long session does not keep every row it ever changed.
pub const UNDO_STEPS: usize = 100;

/// Whether a record may be saved: none of its `required` fields (`required`,
/// each column and label as written) is empty in `values` (by `columns`).
/// No value and empty text are empty; 0 and false are values. The first
/// empty one is refused in Clarity's own words, with its label in the
/// person's language (conformance/required.json).
pub fn check_required(required: &[(&str, &str)], columns: &[&str], values: &[SqlValue]) -> Result<()> {
    match first_required_empty(required, columns, values) {
        Some((_, text)) => Err(Error::Refused(text)),
        None => Ok(()),
    }
}

/// The first `required` field that is empty in `values`, with its column and
/// why in Clarity's own words; none when every one has a value.
fn first_required_empty(required: &[(&str, &str)], columns: &[&str], values: &[SqlValue]) -> Option<(String, ui::Text)> {
    required.iter().find_map(|(column, label)| {
        let value = columns.iter().position(|c| c == column).and_then(|at| values.get(at));
        let empty = matches!(value, None | Some(SqlValue::Null)) || matches!(value, Some(SqlValue::Text(t)) if t.is_empty());
        empty.then(|| {
            let shown = match label.strip_prefix('@') {
                Some(key) => i18n::text(key),
                None => label.to_string(),
            };
            (column.to_string(), ui::Text::keyed("fieldRequired", "{field} is required").with("field", ui::Slot::text(shown)))
        })
    })
}

/// Why the databases did not open, as the person reads it (DESIGN 5.27,
/// conformance/unconnected.json): in Clarity's own words, which the project
/// translates, with this runtime's message in the slot.
pub fn unconnected_reason(err: &Error) -> ui::Text {
    match err {
        Error::NotKept(_) => ui::Text::key("unconnectedNotKept"),
        Error::Storage(what) => ui::Text::key("unconnectedFailed").with("problem", ui::Slot::text(what.clone())),
        other => ui::Text::key("unconnectedFailed").with("problem", ui::Slot::text(other.to_string())),
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Contract(what) => write!(f, "condition failed: {what}"),
            Error::NotFound { table, id: Some(id) } => write!(f, "there is no {table} with id {id}"),
            Error::NotFound { table, id: None } => write!(f, "no {table} is set"),
            Error::InUse { table, id } => write!(f, "the {table} with id {id} is still referred to"),
            Error::Invalid(what) => write!(f, "invalid value: {what}"),
            Error::Storage(what) => write!(f, "storage: {what}"),
            Error::NotKept(setting) => write!(f, "storage: the secret setting {setting} is not kept yet: the settings name the connection"),
            Error::Refused(what) | Error::Required { text: what, .. } => f.write_str(&what.show()),
            Error::Engine(what) | Error::Value(what) => f.write_str(what),
            Error::Outside { position, count } => write!(f, "there is no item {position} in a list of {count}"),
            Error::DividedByZero => f.write_str("division by zero"),
        }
    }
}

impl std::error::Error for Error {}

pub type Result<T> = std::result::Result<T, Error>;

/// Checks a `require` line of a function or action.
/// The date where the application runs: Clarity's `today()`.
pub fn today() -> NaiveDate {
    chrono::Local::now().date_naive()
}

/// The date and time where the application runs, to the second: Clarity's `now()`.
pub fn now() -> NaiveDateTime {
    use chrono::{SubsecRound, Timelike};
    let now = chrono::Local::now().naive_local().trunc_subsecs(0);
    now.with_nanosecond(0).unwrap_or(now)
}

pub fn require(holds: bool, what: &str) -> Result<()> {
    if holds { Ok(()) } else { Err(Error::Contract(what.to_string())) }
}

/// Checks an `ensure` line of a function or action.
pub fn ensure(holds: bool, what: &str) -> Result<()> {
    require(holds, what)
}

/// A record of an entity, as generated code describes it.
pub trait Record: Sized + Clone {
    /// The data source the records live in; empty for the default one.
    const SOURCE: &'static str = "";
    /// The table the records are stored in.
    const TABLE: &'static str;
    /// The integer column that identifies a record.
    const KEY: &'static str = "id";
    /// The stored columns, without `id`, in the order of `to_values`.
    const COLUMNS: &'static [&'static str];
    /// The columns of the `image` fields, which reading records gives only
    /// whether there is a picture, and saving leaves alone when the picture
    /// is the one stored.
    const PICTURES: &'static [picture::PictureColumn] = &[];
    /// The `required` fields, each its column and its label as written (a
    /// key with its `@`, or the text): a save refuses the record while one
    /// is empty (conformance/required.json).
    const REQUIRED: &'static [(&'static str, &'static str)] = &[];
    /// The column of the record's version (conformance/versions.json):
    /// `row_version` for an owned entity, the column an external entity
    /// names, or None for an entity whose saves are not checked.
    const VERSION: Option<&'static str> = None;
    fn id(&self) -> Id;
    fn set_id(&mut self, id: Id);
    fn to_values(&self) -> Vec<SqlValue>;
    /// Builds a record from values in `COLUMNS` order.
    fn from_values(id: Id, values: &[SqlValue]) -> Result<Self>;
    /// The version the record was read or last saved with; 0 for a new one.
    fn version(&self) -> i64 {
        0
    }
    fn set_version(&mut self, _version: i64) {}
    /// Why a save or delete of this record is refused when someone saved it
    /// since: `current` is the record as it is stored now, whose fields an
    /// entity's own text may name, and `db` loads what they refer to
    /// (`{current.changedBy.name}`). Clarity's `savedSince` by default.
    fn saved_since(_db: &Db, _current: &Self) -> ui::Text {
        saved_since()
    }

    /// Whether the entity has data events. A save or delete then runs
    /// with its events in one transaction: when an event fails, nothing
    /// of it is kept.
    const EVENTS: bool = false;
    /// Whether records refer to this one with `cascade`: deleting it deletes
    /// them first (`cascade`), in the transaction of its delete.
    const CASCADES: bool = false;
    /// Deletes the records that refer to record `id` with `cascade`, each as
    /// any record is deleted: with its own cascades and data events.
    fn cascade(_db: &Db, _id: Id) -> Result<()> {
        Ok(())
    }

    fn before_save(&mut self, _db: &Db) -> Result<()> {
        Ok(())
    }

    fn after_save(&mut self, _db: &Db) -> Result<()> {
        Ok(())
    }

    fn before_delete(&mut self, _db: &Db) -> Result<()> {
        Ok(())
    }

    fn after_delete(&mut self, _db: &Db) -> Result<()> {
        Ok(())
    }
}

/// How a value appears in text, for messages and `"text" + value`.
pub trait Show {
    fn show(&self) -> String;
}

impl Show for String {
    fn show(&self) -> String {
        self.clone()
    }
}

impl Show for &str {
    fn show(&self) -> String {
        (*self).to_string()
    }
}

impl Show for i64 {
    fn show(&self) -> String {
        self.to_string()
    }
}

impl Show for Decimal {
    fn show(&self) -> String {
        self.to_string()
    }
}

impl Show for bool {
    fn show(&self) -> String {
        if *self { "yes".into() } else { "no".into() }
    }
}

impl Show for Option<NaiveDate> {
    fn show(&self) -> String {
        self.map(|d| d.to_string()).unwrap_or_default()
    }
}

impl Show for Option<NaiveDateTime> {
    fn show(&self) -> String {
        self.map(|d| d.format("%Y-%m-%d %H:%M").to_string()).unwrap_or_default()
    }
}

/// One migration step: its statements, run in order.
pub type Step<'a> = &'a [&'a str];

/// The database of one data source.
struct Source {
    name: String,
    conn: RefCell<Box<dyn Driver>>,
    /// How many saves and deletes with data events are running in it; the
    /// outermost one holds the transaction.
    depth: Cell<usize>,
}

impl Source {
    fn new(name: &str, driver: Box<dyn Driver>) -> Source {
        Source {
            name: name.to_string(),
            conn: RefCell::new(driver),
            depth: Cell::new(0),
        }
    }
}

/// Where a file store keeps its files.
enum StorePlace {
    /// A folder, found once.
    Folder(std::path::PathBuf),
    /// A folder setting of `program`, read again at every use (`filestore
    /// photos "setting:photosFolder"`), and the setting's default.
    Setting { program: String, setting: String, default: String },
}

/// The databases of an application: one per data source.
pub struct Db {
    /// By data source name; the first is the default.
    sources: Vec<Source>,
    /// The file stores, by name.
    stores: Vec<(String, StorePlace)>,
    /// What undo takes back and redo does again (DESIGN 5.29).
    history: RefCell<History>,
    /// The settings of the running handler: the window's data had them when
    /// the call began, and its code sets them before they are kept; a file
    /// store whose folder is a setting reads them first (conformance/settings.json, `now`).
    held: RefCell<serde_json::Map<String, serde_json::Value>>,
    /// Who is using the program and how people sign in (crate::signin).
    #[cfg(feature = "auth")]
    people: signin::People,
}

/// A row of a table as it was before a change and as the change left it;
/// `None` where it was not there.
struct Change {
    source: String,
    table: &'static str,
    key: &'static str,
    columns: &'static [&'static str],
    /// The version column of a versioned entity: undo then compares the
    /// version, not the whole row.
    version: Option<&'static str>,
    id: Id,
    before: Option<Vec<SqlValue>>,
    after: Option<Vec<SqlValue>>,
    /// The version of the row as it was before the change and as it left it.
    before_version: Option<i64>,
    after_version: Option<i64>,
}

/// The database side of undo (DESIGN 5.29): the changes of each handler
/// run that changed something, by the step's id. The screen keeps the edits
/// on its bus, each with the id of the step its handler made, and asks for
/// that step to be undone or done again. Kept until the application closes.
#[derive(Default)]
struct History {
    /// The changes of the step that runs; none outside a step.
    recording: Option<Vec<Change>>,
    /// Each step by its id, and whether it is undone.
    steps: std::collections::BTreeMap<u64, (Vec<Change>, bool)>,
    /// The id of the last step kept.
    last: u64,
    /// The sources the running step holds a transaction in, by name: what
    /// one handler changes is kept or left whole.
    held: Vec<String>,
}

impl Db {
    /// One SQLite database, used for every record.
    #[cfg(feature = "sqlite")]
    pub fn open(path: &Path) -> Result<Db> {
        Ok(Db::single(Box::new(sqlite::Sqlite::open(path)?)))
    }

    /// A SQLite database that lives in memory, for tests.
    #[cfg(feature = "sqlite")]
    pub fn memory() -> Result<Db> {
        Ok(Db::single(Box::new(sqlite::Sqlite::new(rusqlite::Connection::open_in_memory()?)?)))
    }

    #[cfg(feature = "sqlite")]
    fn single(driver: Box<dyn Driver>) -> Db {
        Db {
            sources: vec![Source::new("", driver)],
            stores: Vec::new(),
            history: RefCell::default(),
            held: RefCell::default(),
            #[cfg(feature = "auth")]
            people: Default::default(),
        }
    }

    /// A database per data source: its name, its kind and where it is (a
    /// file for SQLite, a connection for the others). `env:NAME` takes
    /// the location from that environment variable.
    pub fn connect(sources: &[(&str, Dialect, &str)]) -> Result<Db> {
        let sources = sources
            .iter()
            .map(|(name, dialect, at)| Ok(Source::new(name, store::open(*dialect, at)?)))
            .collect::<Result<Vec<_>>>()?;
        Ok(Db {
            sources,
            stores: Vec::new(),
            history: RefCell::default(),
            held: RefCell::default(),
            #[cfg(feature = "auth")]
            people: Default::default(),
        })
    }

    /// Adds the data source that is a file in a format (`datasource logins
    /// csv "imports/logins.csv" external`): its file, found as a SQLite
    /// file's location is, read into a table its entity finds, saves and
    /// deletes in; each change kept is written back to the file.
    #[cfg(all(feature = "formats", feature = "sqlite"))]
    pub fn add_file(&mut self, source: FileSource) -> Result<()> {
        let at = store::location(&crate::data_folder::sqlite_here(source.path))?;
        let driver = file_source::FileDriver::open(&source, std::path::Path::new(&at))?;
        self.sources.retain(|s| s.name != source.name);
        self.sources.push(Source::new(source.name, Box::new(driver)));
        Ok(())
    }

    /// Adds the file store `name` at `location`, a folder (made when it is
    /// not there yet); `env:NAME` takes it from that environment variable.
    pub fn add_store(&mut self, name: &str, location: &str) -> Result<()> {
        let folder = std::path::PathBuf::from(store::location(location)?);
        std::fs::create_dir_all(&folder).map_err(|e| Error::Storage(format!("cannot make the file store {}: {e}", folder.display())))?;
        self.stores.retain(|(n, _)| n != name);
        self.stores.push((name.to_string(), StorePlace::Folder(folder)));
        Ok(())
    }

    /// Adds the file store `name` whose folder is the folder setting
    /// `setting` of `program` (`filestore photos "setting:photosFolder"`),
    /// or `default` while it is not kept; read again at every use, so a
    /// folder chosen while the application runs takes effect at once.
    pub fn add_store_setting(&mut self, name: &str, program: &str, setting: &str, default: &str) -> Result<()> {
        self.stores.retain(|(n, _)| n != name);
        let place = StorePlace::Setting { program: program.to_string(), setting: setting.to_string(), default: default.to_string() };
        self.stores.push((name.to_string(), place));
        self.store_folder(name).map(|_| ())
    }

    /// The settings the running handler has, as its window's data had them
    /// when the call began: a file store whose folder is a setting reads them
    /// before what is kept.
    pub fn hold_settings(&self, settings: &serde_json::Value) {
        *self.held.borrow_mut() = settings.as_object().cloned().unwrap_or_default();
    }

    /// A setting the running handler's code set, before the settings are kept.
    pub fn hold_setting(&self, setting: &str, value: &str) {
        self.held.borrow_mut().insert(setting.to_string(), serde_json::Value::String(value.to_string()));
    }

    /// The folder of the file store `name`, made when it is not there yet.
    fn store_folder(&self, name: &str) -> Result<std::path::PathBuf> {
        let place = self.stores.iter().find(|(n, _)| n == name).map(|(_, p)| p).ok_or_else(|| Error::Storage(format!("there is no file store '{name}'")))?;
        match place {
            StorePlace::Folder(folder) => Ok(folder.clone()),
            StorePlace::Setting { program, setting, default } => {
                let file = settings::file(program).ok_or_else(|| Error::Storage("this system names no folder for application settings".into()))?;
                let settings_folder = file.parent().map(|f| f.display().to_string()).unwrap_or_default();
                let kept = serde_json::Value::String(settings::now(&self.held.borrow(), &settings::read(program), setting));
                let folder = std::path::PathBuf::from(settings::store_folder_in(settings::OS, &settings_folder, name, &kept, default));
                std::fs::create_dir_all(&folder).map_err(|e| Error::Storage(format!("cannot make the file store {}: {e}", folder.display())))?;
                Ok(folder)
            }
        }
    }

    /// The values of a record as they are saved: a new picture checked, and
    /// written to its file store when it has one, its column then holding
    /// the file's name.
    fn saved_values<R: Record>(&self, record: &R) -> Result<Vec<SqlValue>> {
        let mut values = record.to_values();
        for picture in R::PICTURES {
            let Some(at) = R::COLUMNS.iter().position(|c| *c == picture.column) else { continue };
            let SqlValue::Blob(bytes) = &values[at] else { continue };
            // A file of a `file` field is kept under its own name, in a folder named by its contents.
            if let Some(name_column) = picture.name {
                if let Some(store) = picture.store {
                    let name = R::COLUMNS.iter().position(|c| *c == name_column).and_then(|i| match &values[i] {
                        SqlValue::Text(name) => Some(name.clone()),
                        _ => None,
                    });
                    let path = record_file::store_path(bytes, name.as_deref().unwrap_or(""));
                    let file = picture::in_store(&self.store_folder(store)?, &path)?;
                    if !file.exists() {
                        if let Some(folder) = file.parent() {
                            std::fs::create_dir_all(folder).map_err(|e| Error::Storage(format!("cannot make {}: {e}", folder.display())))?;
                        }
                        std::fs::write(&file, bytes).map_err(|e| Error::Storage(format!("cannot write {}: {e}", file.display())))?;
                    }
                    values[at] = SqlValue::Text(path);
                }
                continue;
            }
            let name = picture::file_name(bytes)?;
            if let Some(store) = picture.store {
                let file = self.store_folder(store)?.join(&name);
                if !file.exists() {
                    std::fs::write(&file, bytes).map_err(|e| Error::Storage(format!("cannot write {}: {e}", file.display())))?;
                }
                values[at] = SqlValue::Text(name);
            }
        }
        Ok(values)
    }

    /// The picture of field `column` of record `id`, read from the database
    /// or from its file store; none when the record has none.
    pub fn picture<R: Record>(&self, id: Id, column: &str) -> Result<Option<Vec<u8>>> {
        let picture = R::PICTURES
            .iter()
            .find(|p| p.column == column)
            .ok_or_else(|| Error::Storage(format!("{} has no picture '{column}'", R::TABLE)))?;
        let value = {
            let mut conn = self.conn(R::SOURCE)?;
            let d = conn.dialect();
            let sql = format!("SELECT {} FROM {} WHERE {} = {}", d.quote(column), d.quote(R::TABLE), d.quote(R::KEY), d.mark(1));
            let rows = conn.rows(&sql, &[SqlValue::Integer(id)])?;
            let row = rows.into_iter().next().ok_or(Error::NotFound { table: R::TABLE, id: Some(id) })?;
            row.into_iter().next().unwrap_or(SqlValue::Null)
        };
        match (picture.store, value) {
            (_, SqlValue::Null) => Ok(None),
            (None, SqlValue::Blob(bytes)) => Ok(Some(bytes)),
            (Some(store), SqlValue::Text(path)) if !path.is_empty() => {
                let file = picture::in_store(&self.store_folder(store)?, &path)?;
                std::fs::read(&file).map(Some).map_err(|e| Error::Storage(format!("cannot read {}: {e}", file.display())))
            }
            (_, SqlValue::Text(_)) => Ok(None),
            (_, other) => Err(Error::Storage(format!("{column}: {other:?} is no picture"))),
        }
    }

    /// Another record's picture for a field kept in `to` (none: the
    /// database), as code copies it (`album.cover = other.cover`). `value` is
    /// field `column` of record `id`, kept in `from`. A picture in hand is
    /// copied as it is, a stored one is read first, and a file of a store
    /// stays linked only in that same store.
    pub fn copied_picture<R: Record>(&self, value: &Option<Picture>, id: Id, column: &str, from: Option<&str>, to: Option<&str>) -> Result<Option<Picture>> {
        Ok(match value {
            None => None,
            Some(Picture::New(bytes)) => Some(Picture::New(bytes.clone())),
            Some(Picture::Stored) => self.picture::<R>(id, column)?.map(Picture::New),
            Some(Picture::InStore(path)) => match from {
                Some(store) if Some(store) == to => Some(Picture::InStore(path.clone())),
                Some(store) => Some(Picture::New(self.store_file(store, path)?)),
                None => return Err(Error::Storage(format!("{column} is kept in the database, not in a file store"))),
            },
        })
    }

    /// Another record's file, with its name, as `copied_picture` copies a picture.
    pub fn copied_file<R: Record>(&self, value: &Option<RecordFile>, id: Id, column: &str, from: Option<&str>, to: Option<&str>) -> Result<Option<RecordFile>> {
        let Some(file) = value else { return Ok(None) };
        let content = self.copied_picture::<R>(&Some(file.content.clone()), id, column, from, to)?;
        Ok(content.map(|content| RecordFile { name: file.name.clone(), content }))
    }

    /// The data source `source`. With one database, every record is in it.
    fn source(&self, source: &str) -> Result<&Source> {
        let single = self.sources.len() == 1;
        self.sources
            .iter()
            .find(|s| single || source.is_empty() || s.name == source)
            .ok_or_else(|| Error::Storage(format!("there is no data source '{source}'")))
    }

    fn conn(&self, source: &str) -> Result<RefMut<'_, Box<dyn Driver>>> {
        Ok(self.source(source)?.conn.borrow_mut())
    }

    /// Runs `run` in a transaction of `source`, or in the one that is open
    /// already: a save that an event of another save makes is part of it.
    fn atomic<T>(&self, source: &str, run: impl FnOnce() -> Result<T>) -> Result<T> {
        let at = self.source(source)?;
        let outer = at.depth.get() == 0;
        if outer {
            let mut conn = at.conn.borrow_mut();
            let begin = conn.dialect().begin();
            conn.batch(begin)?;
        }
        at.depth.set(at.depth.get() + 1);
        let result = run();
        at.depth.set(at.depth.get() - 1);
        // A step that holds the transaction ends it itself.
        if at.depth.get() == 0 {
            let mut conn = at.conn.borrow_mut();
            let d = conn.dialect();
            match &result {
                Ok(_) => {
                    // A commit that fails leaves nothing half kept.
                    if let Err(failure) = conn.batch(d.commit()) {
                        let _ = conn.batch(d.rollback());
                        return Err(failure.into());
                    }
                }
                // The error that made it roll back is the one to report.
                Err(_) => {
                    let _ = conn.batch(d.rollback());
                }
            }
        }
        result
    }

    /// Runs SQL without parameters in the database of `source`, for tools
    /// and tests; generated code reads and writes through records.
    pub fn batch(&self, source: &str, sql: &str) -> Result<()> {
        Ok(self.conn(source)?.batch(sql)?)
    }

    /// The rows SQL reads in the database of `source`, for tools and tests.
    pub fn rows(&self, source: &str, sql: &str, params: &[SqlValue]) -> Result<Vec<Vec<SqlValue>>> {
        Ok(self.conn(source)?.rows(sql, params)?)
    }

    /// The kind of database `source` is.
    pub fn dialect(&self, source: &str) -> Result<Dialect> {
        Ok(self.conn(source)?.dialect())
    }

    /// The number of migration steps applied so far to the default database.
    pub fn schema_version(&self) -> Result<usize> {
        schema_version(&mut **self.conn("")?)
    }

    /// `migrate_source` for the default database.
    pub fn migrate(&mut self, steps: &[Step]) -> Result<usize> {
        self.migrate_source("", steps)
    }

    /// Applies the steps of `source` that its database has not had yet,
    /// each on its own.
    pub fn migrate_source(&mut self, source: &str, steps: &[Step]) -> Result<usize> {
        let mut conn = self.conn(source)?;
        let done = schema_version(&mut **conn)?;
        // A database that already has a schema is backed up before it changes (docs/BACKUP-PLAN.md).
        if done > 0 && done < steps.len() {
            backup::before_migration(&mut **conn, done + 1)?;
        }
        for (i, step) in steps.iter().enumerate().skip(done) {
            conn.apply(i + 1, step)?;
        }
        Ok(steps.len().saturating_sub(done))
    }

    /// Inserts a new record (and gives it its id) or updates a stored one,
    /// with the entity's data events around it. A record someone saved
    /// since it was read is refused, changing nothing (`savedSince`).
    pub fn save<R: Record>(&self, record: &mut R) -> Result<()> {
        self.save_with(record, false)
    }

    /// Saves a record regardless of its version (`save ... anyway`): what
    /// someone saved since is written over, on purpose.
    pub fn save_anyway<R: Record>(&self, record: &mut R) -> Result<()> {
        self.save_with(record, true)
    }

    /// Reads a record again as it is stored now, with its version.
    pub fn reload<R: Record>(&self, record: &mut R) -> Result<()> {
        *record = self.get(record.id())?;
        Ok(())
    }

    fn save_with<R: Record>(&self, record: &mut R, anyway: bool) -> Result<()> {
        // A person's secret changed by this save closes their other sessions (crate::signin).
        #[cfg(feature = "auth")]
        let secrets = self.secrets_of(R::TABLE, record.id());
        let saved = self.save_record(record, anyway);
        #[cfg(feature = "auth")]
        if saved.is_ok() {
            self.secrets_saved(R::TABLE, record.id(), secrets);
        }
        saved
    }

    fn save_record<R: Record>(&self, record: &mut R, anyway: bool) -> Result<()> {
        if !R::EVENTS {
            return self.store(record, anyway);
        }
        let (id, version) = (record.id(), record.version());
        let saved = self.atomic(R::SOURCE, || {
            record.before_save(self)?;
            self.store(record, anyway)?;
            record.after_save(self)
        });
        // Nothing was kept, so a new record is still new, at the version it was read with.
        if saved.is_err() {
            record.set_id(id);
            record.set_version(version);
        }
        saved
    }

    fn store<R: Record>(&self, record: &mut R, anyway: bool) -> Result<()> {
        // A refusal says which record and column, so a window shows it at the input bound to it.
        if let Some((column, text)) = first_required_empty(R::REQUIRED, R::COLUMNS, &record.to_values()) {
            return Err(Error::Required { table: R::TABLE, id: record.id(), column, text });
        }
        self.enlist(R::SOURCE)?;
        let recording = self.history.borrow().recording.is_some();
        let (before, before_version) = if recording && record.id() != 0 { self.state(R::SOURCE, R::TABLE, R::KEY, R::COLUMNS, R::VERSION, record.id())? } else { (None, None) };
        self.store_row(record, anyway)?;
        if recording {
            let (after, after_version) = self.state(R::SOURCE, R::TABLE, R::KEY, R::COLUMNS, R::VERSION, record.id())?;
            let change = Change { source: R::SOURCE.to_string(), table: R::TABLE, key: R::KEY, columns: R::COLUMNS, version: R::VERSION, id: record.id(), before, after, before_version, after_version };
            self.record(change);
        }
        Ok(())
    }

    fn store_row<R: Record>(&self, record: &mut R, anyway: bool) -> Result<()> {
        let values = self.saved_values(record)?;
        let mut conn = self.conn(R::SOURCE)?;
        let d = conn.dialect();
        let picture = |c: &str| R::PICTURES.iter().any(|p| p.column == c);
        if record.id() == 0 {
            // An empty or kept picture is left to the column's NULL, so no
            // NULL is bound to a binary column (SQL Server refuses that).
            let (mut columns, mut values): (Vec<&str>, Vec<SqlValue>) = R::COLUMNS
                .iter()
                .zip(values)
                .filter(|(c, v)| !(picture(c) && matches!(v, SqlValue::Null | SqlValue::Kept)))
                .map(|(c, v)| (*c, v))
                .unzip();
            // A new record starts at version 1.
            if let Some(version) = R::VERSION {
                columns.push(version);
                values.push(SqlValue::Integer(1));
            }
            let id = conn.insert(&d.insert(R::TABLE, R::KEY, &columns), &values).map_err(unfit)?;
            record.set_id(id);
            if R::VERSION.is_some() {
                record.set_version(1);
            }
            return Ok(());
        }
        // A kept picture stays as it is; an emptied one is set to NULL as text.
        let mut sets = Vec::new();
        let mut params = Vec::new();
        for (column, value) in R::COLUMNS.iter().zip(values) {
            match value {
                SqlValue::Kept => {}
                SqlValue::Null if picture(column) => sets.push(format!("{} = NULL", d.quote(column))),
                value => {
                    params.push(value);
                    sets.push(format!("{} = {}", d.quote(column), d.mark(params.len())));
                }
            }
        }
        // Each save adds one to the version; a checked one writes only over the version it read.
        if let Some(version) = R::VERSION {
            sets.push(format!("{0} = {0} + 1", d.quote(version)));
        }
        if sets.is_empty() {
            return if exists::<R>(&mut **conn, record.id())? { Ok(()) } else { Err(Error::NotFound { table: R::TABLE, id: Some(record.id()) }) };
        }
        let mut sql = format!("UPDATE {} SET {} WHERE {} = {}", d.quote(R::TABLE), sets.join(", "), d.quote(R::KEY), d.mark(params.len() + 1));
        params.push(SqlValue::Integer(record.id()));
        let checked = R::VERSION.filter(|_| !anyway);
        if let Some(version) = checked {
            params.push(SqlValue::Integer(record.version()));
            sql.push_str(&format!(" AND {} = {}", d.quote(version), d.mark(params.len())));
        }
        // MySQL counts only the rows whose values changed, so an update
        // that changes nothing is told apart from a missing record (one
        // with a version always changes).
        if conn.execute(&sql, &params).map_err(unfit)? == 0 {
            if !exists::<R>(&mut **conn, record.id())? {
                return Err(Error::NotFound { table: R::TABLE, id: Some(record.id()) });
            }
            if checked.is_some() {
                drop(conn);
                return Err(self.refusal::<R>(record.id()));
            }
        }
        match R::VERSION {
            Some(_) if anyway => {
                let stored = stored_version::<R>(&mut **conn, record.id())?;
                record.set_version(stored);
            }
            Some(_) => record.set_version(record.version() + 1),
            None => {}
        }
        Ok(())
    }

    /// The refusal of a save or delete of record `id` that someone saved
    /// since, in the entity's words about the record as stored now.
    fn refusal<R: Record>(&self, id: Id) -> Error {
        match self.get::<R>(id) {
            Ok(current) => Error::Refused(R::saved_since(self, &current)),
            Err(_) => Error::Refused(saved_since()),
        }
    }

    /// Removes a stored record, with the entity's data events around it.
    pub fn delete<R: Record>(&self, record: &R) -> Result<()> {
        if !R::EVENTS && !R::CASCADES {
            return self.remove(record);
        }
        let mut record = record.clone();
        self.atomic(R::SOURCE, || {
            record.before_delete(self)?;
            // What cascades from it goes first, so no reference is left behind.
            R::cascade(self, record.id())?;
            self.remove(&record)?;
            record.after_delete(self)
        })
    }

    fn remove<R: Record>(&self, record: &R) -> Result<()> {
        self.enlist(R::SOURCE)?;
        let recording = self.history.borrow().recording.is_some();
        let (before, before_version) = if recording { self.state(R::SOURCE, R::TABLE, R::KEY, R::COLUMNS, R::VERSION, record.id())? } else { (None, None) };
        self.remove_row(record)?;
        if recording {
            let change = Change { source: R::SOURCE.to_string(), table: R::TABLE, key: R::KEY, columns: R::COLUMNS, version: R::VERSION, id: record.id(), before, after: None, before_version, after_version: None };
            self.record(change);
        }
        Ok(())
    }

    fn remove_row<R: Record>(&self, record: &R) -> Result<()> {
        let mut conn = self.conn(R::SOURCE)?;
        let d = conn.dialect();
        let mut sql = format!("DELETE FROM {} WHERE {} = {}", d.quote(R::TABLE), d.quote(R::KEY), d.mark(1));
        let mut params = vec![SqlValue::Integer(record.id())];
        // A record someone saved since it was read is not deleted.
        if let Some(version) = R::VERSION {
            sql.push_str(&format!(" AND {} = {}", d.quote(version), d.mark(2)));
            params.push(SqlValue::Integer(record.version()));
        }
        match conn.execute(&sql, &params) {
            Ok(0) if R::VERSION.is_some() && exists::<R>(&mut **conn, record.id())? => {
                drop(conn);
                Err(self.refusal::<R>(record.id()))
            }
            Ok(_) => Ok(()),
            Err(Failure::Reference(_)) => Err(Error::InUse {
                table: R::TABLE,
                id: record.id(),
            }),
            Err(failure) => Err(failure.into()),
        }
    }

    /// Runs a handler as one step, which undo takes back whole (DESIGN
    /// 5.29): its id, when it changed anything, is `last_step`. Everything
    /// it changes is one transaction in each source it changes: kept when
    /// it ends, left whole when it fails, so it leaves nothing behind. A
    /// step inside a step is part of it. The last `UNDO_STEPS` are kept.
    pub fn step<T>(&self, run: impl FnOnce() -> Result<T>) -> Result<T> {
        if self.history.borrow().recording.is_some() {
            return run();
        }
        self.history.borrow_mut().recording = Some(Vec::new());
        let mut result = run();
        let (changes, held) = {
            let mut history = self.history.borrow_mut();
            (history.recording.take().unwrap_or_default(), std::mem::take(&mut history.held))
        };
        let kept = self.release(&held, result.is_ok());
        if let (Ok(_), Err(failed)) = (&result, kept) {
            result = Err(failed);
        }
        if result.is_ok() && !changes.is_empty() {
            let mut history = self.history.borrow_mut();
            history.last += 1;
            let id = history.last;
            history.steps.insert(id, (changes, false));
            while history.steps.len() > UNDO_STEPS {
                history.steps.pop_first();
            }
        }
        result
    }

    /// Makes the running step hold a transaction in `source`, from its first
    /// change there; outside a step, nothing.
    fn enlist(&self, source: &str) -> Result<()> {
        let at = self.source(source)?;
        {
            let history = self.history.borrow();
            if history.recording.is_none() || history.held.contains(&at.name) {
                return Ok(());
            }
        }
        if at.depth.get() == 0 {
            let mut conn = at.conn.borrow_mut();
            let begin = conn.dialect().begin();
            conn.batch(begin)?;
        }
        at.depth.set(at.depth.get() + 1);
        self.history.borrow_mut().held.push(at.name.clone());
        Ok(())
    }

    /// Ends the transactions a step held: kept (`keep`) or rolled back. When
    /// one cannot be kept, the ones not kept yet are rolled back too.
    fn release(&self, held: &[String], keep: bool) -> Result<()> {
        let mut keep = keep;
        let mut failed = Ok(());
        for name in held {
            let Ok(at) = self.source(name) else { continue };
            at.depth.set(at.depth.get().saturating_sub(1));
            if at.depth.get() > 0 {
                continue;
            }
            let mut conn = at.conn.borrow_mut();
            let d = conn.dialect();
            if keep {
                if let Err(err) = conn.batch(d.commit()) {
                    let _ = conn.batch(d.rollback());
                    keep = false;
                    failed = Err(err.into());
                }
            } else {
                let _ = conn.batch(d.rollback());
            }
        }
        failed
    }

    /// The id of the last step a handler made, to undo it later by; 0 before any.
    pub fn last_step(&self) -> u64 {
        self.history.borrow().last
    }

    /// Takes back step `id`: every row it changed as it was, with its own
    /// id. Refused, changing nothing, when one of its rows changed since;
    /// false when there is no such step, or it is undone already.
    pub fn undo(&self, id: u64) -> Result<bool> {
        self.replay_steps(&[id], true)
    }

    /// Does step `id` again after an undo; false when it is not undone.
    pub fn redo(&self, id: u64) -> Result<bool> {
        self.replay_steps(&[id], false)
    }

    /// Takes back (`back`) or does again the steps of one edit, in the order
    /// given, as one: all of them or, refused, none. A step older than the
    /// ones kept is refused (`undoTooOld`); false when none of them is in
    /// the state to be replayed.
    pub fn replay_steps(&self, ids: &[u64], back: bool) -> Result<bool> {
        let mut taken: Vec<(u64, Vec<Change>)> = Vec::new();
        {
            let mut history = self.history.borrow_mut();
            let last = history.last;
            for id in ids {
                match history.steps.get_mut(id) {
                    Some((changes, undone)) if *undone != back => taken.push((*id, std::mem::take(changes))),
                    Some(_) => {}
                    // A step never made is nothing to replay; one made and no longer kept is refused.
                    None if *id != 0 && *id <= last => {
                        // Put back what was taken, and refuse.
                        for (id, changes) in taken.drain(..) {
                            if let Some((kept, _)) = history.steps.get_mut(&id) {
                                *kept = changes;
                            }
                        }
                        return Err(Error::Refused(undo_too_old()));
                    }
                    None => {}
                }
            }
        }
        if taken.is_empty() {
            return Ok(false);
        }
        let replayed = self.replay(&mut taken, back);
        let mut history = self.history.borrow_mut();
        for (id, changes) in taken {
            if let Some((kept, undone)) = history.steps.get_mut(&id) {
                *kept = changes;
                if replayed.is_ok() {
                    *undone = back;
                }
            }
        }
        replayed.map(|()| true)
    }

    fn record(&self, change: Change) {
        if let Some(recording) = self.history.borrow_mut().recording.as_mut() {
            recording.push(change);
        }
    }

    /// Puts the rows of steps back (`back`) or forward, after checking that
    /// each row is still as the steps left it (by its version, or the whole
    /// row where there is none), all in one transaction per source, checks
    /// included. Each row's new version is noted where the next replay checks it.
    fn replay(&self, steps: &mut [(u64, Vec<Change>)], back: bool) -> Result<()> {
        // The changes in the order they are replayed: the steps as given, each one's changes backwards for an undo.
        let mut order: Vec<(usize, usize)> = Vec::new();
        for (s, (_, changes)) in steps.iter().enumerate() {
            let mut indices: Vec<usize> = (0..changes.len()).collect();
            if back {
                indices.reverse();
            }
            order.extend(indices.into_iter().map(|c| (s, c)));
        }
        let mut sources: Vec<String> = steps.iter().flat_map(|(_, changes)| changes.iter().map(|c| c.source.clone())).collect();
        sources.sort();
        sources.dedup();
        let sources: Vec<&str> = sources.iter().map(String::as_str).collect();
        let changes = std::cell::RefCell::new(steps);
        self.within(&sources, &|| {
            let mut steps = changes.borrow_mut();
            // Each row as the steps left it (its last change undone, its first redone) must still be so.
            let mut seen = Vec::new();
            for &(s, c) in &order {
                let change = &steps[s].1[c];
                let at = (change.source.clone(), change.table, change.id);
                if seen.contains(&at) {
                    continue;
                }
                seen.push(at);
                let (row, version) = self.state(&change.source, change.table, change.key, change.columns, change.version, change.id)?;
                let unchanged = match change.version {
                    Some(_) => version == if back { change.after_version } else { change.before_version },
                    None => &row == if back { &change.after } else { &change.before },
                };
                if !unchanged {
                    return Err(Error::Refused(undo_changed_since()));
                }
            }
            for &(s, c) in &order {
                let change = &steps[s].1[c];
                self.put(change, if back { change.before.as_deref() } else { change.after.as_deref() }, if back { change.before_version } else { change.after_version })?;
            }
            // The version each row has now is what the next replay finds: noted on its last change in this order.
            let mut noted = Vec::new();
            for &(s, c) in order.iter().rev() {
                let change = &steps[s].1[c];
                let at = (change.source.clone(), change.table, change.id);
                if change.version.is_none() || noted.contains(&at) {
                    continue;
                }
                noted.push(at);
                let (_, version) = self.state(&change.source, change.table, change.key, change.columns, change.version, change.id)?;
                let change = &mut steps[s].1[c];
                if back {
                    change.before_version = version;
                } else {
                    change.after_version = version;
                }
            }
            Ok(())
        })
    }

    /// Runs `run` in a transaction of each of `sources`.
    fn within(&self, sources: &[&str], run: &dyn Fn() -> Result<()>) -> Result<()> {
        match sources.split_first() {
            None => run(),
            Some((first, rest)) => self.atomic(first, || self.within(rest, run)),
        }
    }

    /// A row's raw values (its columns, by `columns`) and its version (by
    /// `version`), or `None` when it is not there.
    #[allow(clippy::too_many_arguments)]
    fn state(&self, source: &str, table: &str, key: &str, columns: &[&str], version: Option<&str>, id: Id) -> Result<(Option<Vec<SqlValue>>, Option<i64>)> {
        let mut conn = self.conn(source)?;
        let d = conn.dialect();
        let mut names: Vec<String> = std::iter::once(key).chain(columns.iter().copied()).map(|c| d.quote(c)).collect();
        if let Some(version) = version {
            names.push(d.quote(version));
        }
        let sql = format!("SELECT {} FROM {} WHERE {} = {}", names.join(", "), d.quote(table), d.quote(key), d.mark(1));
        let mut rows = conn.rows(&sql, &[SqlValue::Integer(id)])?;
        if rows.is_empty() {
            return Ok((None, None));
        }
        let mut row = rows.remove(0);
        let stored = match version {
            Some(_) => Some(sql::get_integer("version", &row.pop().unwrap_or(SqlValue::Null))?),
            None => None,
        };
        row.remove(0);
        Ok((Some(row), stored))
    }

    /// Makes a row so: gone, or with these values and its own id.
    /// A versioned row put back gets a version past both its current one
    /// and `version`, the one of the state it returns to, so a copy read
    /// before is refused.
    fn put(&self, change: &Change, values: Option<&[SqlValue]>, version: Option<i64>) -> Result<()> {
        let (row, current) = self.state(&change.source, change.table, change.key, change.columns, change.version, change.id)?;
        let there = row.is_some();
        let next = current.max(version).unwrap_or(0) + 1;
        let mut conn = self.conn(&change.source)?;
        let d = conn.dialect();
        let table = d.quote(change.table);
        let key = d.quote(change.key);
        let id = SqlValue::Integer(change.id);
        match values {
            None if there => {
                conn.execute(&format!("DELETE FROM {table} WHERE {key} = {}", d.mark(1)), &[id])?;
            }
            None => {}
            Some(values) if there => {
                let mut sets: Vec<String> = change.columns.iter().enumerate().map(|(i, c)| format!("{} = {}", d.quote(c), d.mark(i + 1))).collect();
                let mut params = values.to_vec();
                if let Some(column) = change.version {
                    params.push(SqlValue::Integer(next));
                    sets.push(format!("{} = {}", d.quote(column), d.mark(params.len())));
                }
                if !sets.is_empty() {
                    params.push(id);
                    conn.execute(&format!("UPDATE {table} SET {} WHERE {key} = {}", sets.join(", "), d.mark(params.len())), &params)?;
                }
            }
            Some(values) => {
                let mut names: Vec<String> = std::iter::once(key.clone()).chain(change.columns.iter().map(|c| d.quote(c))).collect();
                let mut params = vec![id];
                params.extend(values.iter().cloned());
                if let Some(column) = change.version {
                    names.push(d.quote(column));
                    params.push(SqlValue::Integer(next));
                }
                let marks = (1..=params.len()).map(|i| d.mark(i)).collect::<Vec<_>>().join(", ");
                let names = names.join(", ");
                let insert = format!("INSERT INTO {table} ({names}) VALUES ({marks})");
                // SQL Server takes a key of its own counting only when asked to.
                if d == Dialect::Mssql {
                    conn.batch(&format!("SET IDENTITY_INSERT {table} ON"))?;
                    let inserted = conn.execute(&insert, &params);
                    conn.batch(&format!("SET IDENTITY_INSERT {table} OFF"))?;
                    inserted?;
                } else {
                    conn.execute(&insert, &params)?;
                }
            }
        }
        Ok(())
    }

    /// The records a query finds, in its order.
    pub fn find<R: Record>(&self, query: &Query) -> Result<Vec<R>> {
        let mut conn = self.conn(R::SOURCE)?;
        let d = conn.dialect();
        let (sql, params) = query.sql(d, R::TABLE, R::KEY, &select_columns::<R>(d));
        records(&mut **conn, &sql, &params)
    }

    fn select<R: Record>(&self, filter: impl Fn(Dialect) -> String, params: &[SqlValue]) -> Result<Vec<R>> {
        let mut conn = self.conn(R::SOURCE)?;
        let d = conn.dialect();
        let sql = format!("SELECT {} FROM {}{}", select_columns::<R>(d), d.quote(R::TABLE), filter(d));
        records(&mut **conn, &sql, params)
    }

    /// Every stored record of an entity, in the order they were stored.
    pub fn all<R: Record>(&self) -> Result<Vec<R>> {
        self.select(|d| format!(" ORDER BY {}", d.quote(R::KEY)), &[])
    }

    pub fn get<R: Record>(&self, id: Id) -> Result<R> {
        self.select::<R>(|d| format!(" WHERE {} = {}", d.quote(R::KEY), d.mark(1)), &[SqlValue::Integer(id)])?
            .pop()
            .ok_or(Error::NotFound {
                table: R::TABLE,
                id: Some(id),
            })
    }

    /// The record a `ref` field points at.
    pub fn load<R: Record>(&self, id: Option<Id>) -> Result<R> {
        match id {
            Some(id) => self.get(id),
            None => Err(Error::NotFound { table: R::TABLE, id: None }),
        }
    }
}

/// A failed save: a reference to a record that is not there reads better
/// than the database's own words.
fn unfit(failure: Failure) -> Error {
    match failure {
        Failure::Reference(what) => Error::Invalid(format!("a reference does not fit: {what}")),
        other => other.into(),
    }
}

/// The key and the stored columns of a record, for SELECT.
/// The key, the stored columns and the version of a record, for SELECT.
fn select_columns<R: Record>(d: Dialect) -> String {
    std::iter::once(d.quote(R::KEY))
        .chain(R::COLUMNS.iter().map(|c| match R::PICTURES.iter().find(|p| p.column == *c) {
            // Whether there is a picture, not the picture.
            Some(p) if p.store.is_none() => picture::presence(d, c),
            _ => d.quote(c),
        }))
        .chain(R::VERSION.map(|v| d.quote(v)))
        .collect::<Vec<_>>()
        .join(", ")
}

fn records<R: Record>(conn: &mut dyn Driver, sql: &str, params: &[SqlValue]) -> Result<Vec<R>> {
    conn.rows(sql, params)?
        .into_iter()
        .map(|row| {
            let id = sql::get_integer(R::KEY, row.first().unwrap_or(&SqlValue::Null))?;
            let mut record = R::from_values(id, &row[1..=R::COLUMNS.len().min(row.len() - 1)])?;
            if R::VERSION.is_some() {
                record.set_version(sql::get_integer("version", row.last().unwrap_or(&SqlValue::Null))?);
            }
            Ok(record)
        })
        .collect()
}

/// The version record `id` is stored with now.
fn stored_version<R: Record>(conn: &mut dyn Driver, id: Id) -> Result<i64> {
    let Some(version) = R::VERSION else { return Ok(0) };
    let d = conn.dialect();
    let sql = format!("SELECT {} FROM {} WHERE {} = {}", d.quote(version), d.quote(R::TABLE), d.quote(R::KEY), d.mark(1));
    let rows = conn.rows(&sql, &[SqlValue::Integer(id)])?;
    sql::get_integer("version", rows.first().and_then(|r| r.first()).unwrap_or(&SqlValue::Null))
}

fn exists<R: Record>(conn: &mut dyn Driver, id: Id) -> Result<bool> {
    let d = conn.dialect();
    let sql = format!("SELECT {} FROM {} WHERE {} = {}", d.quote(R::KEY), d.quote(R::TABLE), d.quote(R::KEY), d.mark(1));
    Ok(!conn.rows(&sql, &[SqlValue::Integer(id)])?.is_empty())
}

fn schema_version(conn: &mut dyn Driver) -> Result<usize> {
    conn.batch(conn.dialect().version_table())?;
    let rows = conn.rows("SELECT MAX(version) FROM clarity_schema", &[])?;
    let version = rows.first().and_then(|row| row.first()).map_or(Ok(0), |v| sql::get_integer("version", v))?;
    Ok(version as usize)
}
